cd /app && python3 - <<'PY'
p='promql/sort.go'
s=open(p).read()
# Find the parseScientific function block and replace it with a wrapper.
start = s.index('// parseScientific parses a decimal number')
end = s.index('// parseScientificPrefix parses a decimal number')
old = s[start:end]
new = '''// parseScientific parses a decimal number in scientific notation (with an
// optional leading sign, a decimal point and an optional exponent) into an
// arbitrary-precision rational. A bare exponent marker with no following digits
// is rejected.
func parseScientific(s string) (*big.Rat, bool) {
\trat, n, ok := parseScientificPrefix(s)
\tif !ok || n != len(s) {
\t\treturn nil, false
\t}
\treturn rat, true
}

'''
s = s[:start] + new + s[end:]
open(p,'w').write(s)
PY
gofmt -w promql/sort.go && timeout 120 go test ./promql/ -run 'TestCompareLabelValues' -count=1 2>&1 | tail -20
